package Collections_Framework.Set;import java.util.*;public class LINKEDHASHSET {    public static void main(String[] args) {        Set<Integer> set=new LinkedHashSet<>();        set.add(1);        set.add(20);        set.add(32);        set.add(14);        set.add(15);        System.out.println(set);        set.remove(32);        System.out.println(set);    }}//values are printed in insertion order.//duplicates value can't be take